class SlidingWindowRateLimiter:
    """Sliding-window rate limiter backed by a circular buffer.

    Tracks timestamps of requests in a fixed-size circular buffer.  A request
    is allowed only if fewer than *max_requests* timestamps fall within the
    trailing *window_seconds* window.  Old timestamps are lazily evicted on
    each check so the buffer never holds stale entries.

    Thread-safe: all public methods acquire an internal lock.

    Parameters
    ----------
    max_requests : int
        Maximum number of requests allowed in the sliding window.
    window_seconds : float
        Width of the sliding window in seconds.
    time_fn : callable, optional
        Monotonic clock source (default ``time.monotonic``).  Inject a fake
        clock for deterministic testing.
    """

    def __init__(
        self,
        max_requests: int,
        window_seconds: float,
        time_fn: Optional[Callable[[], float]] = None,
    ):
        if max_requests < 1:
            raise ValueError("max_requests must be >= 1")
        if window_seconds <= 0:
            raise ValueError("window_seconds must be > 0")
        self._max = max_requests
        self._window = window_seconds
        self._time: Callable[[], float] = time_fn or time.monotonic
        self._buf = CircularBuffer(max_requests)
        self._lock = threading.Lock()

    @property
    def max_requests(self) -> int:
        return self._max

    @property
    def window_seconds(self) -> float:
        return self._window

    def _evict(self, now: float) -> None:
        """Remove timestamps older than the sliding window."""
        cutoff = now - self._window
        while self._buf and self._buf.peek() <= cutoff:
            self._buf.pop()

    def allow(self) -> bool:
        """Return True and record the request if within quota, else False."""
        now = self._time()
        with self._lock:
            self._evict(now)
            if len(self._buf) < self._max:
                self._buf.push(now)
                return True
            return False

    def remaining(self) -> int:
        """Return how many more requests are allowed right now."""
        now = self._time()
        with self._lock:
            self._evict(now)
            return self._max - len(self._buf)

    def reset(self) -> None:
        """Clear all recorded timestamps (e.g. after auth refresh)."""
        with self._lock:
            self._buf.clear()

    def retry_after(self) -> float:
        """Seconds until the next request would be allowed (0 if allowed now)."""
        now = self._time()
        with self._lock:
            self._evict(now)
            if len(self._buf) < self._max:
                return 0.0
            oldest = self._buf.peek()
            return max(0.0, self._window - (now - oldest))

    def __repr__(self) -> str:
        return (
            f"SlidingWindowRateLimiter(max_requests={self._max}, "
            f"window_seconds={self._window})"
        )
